import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { mockFetchMachinesForUser } from '../services/api';

export default function DashboardPage() {
  const navigate = useNavigate();
  const { user, isAuthenticated } = useAuth();
  const [machine, setMachine] = useState(null);
  const [loading, setLoading] = useState(false);
  const [notFound, setNotFound] = useState(false);

  // Активная вкладка: 'info' (Общая информация), 'TO', 'claims'
  const [activeTab, setActiveTab] = useState('info');

  // Данные машин (для раздела "Общая информация")
  const [machines, setMachines] = useState([]);
  const [filters, setFilters] = useState({
    date_shipment_from_factory: '',
    model_machine: '',
    model_engine: '',
    model_transmission: '',
    model_controlled_bridge: '',
    model_driving_bridge: '',
    serial_number_machine: '',
  });

  // Сортировка по умолчанию - по date_shipment_from_factory (возрастание)
  const [sortKey, setSortKey] = useState('date_shipment_from_factory');
  const [sortAsc, setSortAsc] = useState(true);

  // Имя пользователя для отображения (из user)
  const userName = user?.customer?.name
    || user?.service_company?.name
    //|| 'Пользователь';

  // Загрузка данных машин при переходе во вкладку "Общая информация"
  useEffect(() => {
    if (activeTab !== 'info') return;

    const loadMachines = async () => {
      try {
        
        const res = await mockFetchMachinesForUser (user);
        if (res.ok) {
           const data = await res.json();
           setMachines(data);
         } else {
           setMachines([]);
         }
    } catch {
      setNotFound(true);
    } finally {
      setLoading(false);
    }
};

    loadMachines();
  }, [activeTab, user?.id]);

  // Фильтрация по всем полям таблицы
  const filtered = useMemo(() => {
    const f = filters;
    const matches = (val, filter) =>
      !filter || String(val ?? '').toLowerCase().includes(filter.toLowerCase());

    return machines.filter((m) =>
      matches(m.date_shipment_from_factory, f.date) &&
      matches(m.model_machine, f.model_machine) &&
      matches(m.model_engine, f.model_engine) &&
      matches(m.model_transmission, f.model_transmission) &&
      matches(m.model_controlled_bridge, f.model_controlled_bridge) &&
      matches(m.model_driving_bridge, f.model_driving_bridge) &&
      matches(m.serial_number_machine, f.serial_number_machine)
    );
  }, [machines, filters]);

  // Сортировка результата
  const sorted = useMemo(() => {
    const arr = [...filtered];
    arr.sort((a, b) => {
      const av = new Date(a[sortKey]);
      const bv = new Date(b[sortKey]);
      // Если даты не валидны, сравниваем по строке
      if (Number.isNaN(av) || Number.isNaN(bv)) {
        const sa = String(a[sortKey] ?? '');
        const sb = String(b[sortKey] ?? '');
        return sortAsc ? sa.localeCompare(sb) : sb.localeCompare(sa);
      }
      return sortAsc ? av - bv : bv - av;
    });
    return arr;
  }, [filtered, sortKey, sortAsc]);

  // Если загружается авторизация
  if (loading) {
    return null;
  }

  return (
    <div className="dashboard-page" style={{ padding: 16 }}>
      {/* Верхний заголовок слева */}
      <div className="page-header" style={{ display: 'flex', justifyContent: 'flex-start', alignItems: 'center' }}>
        <h2>Панель управления</h2>
      </div>

      {/* Имя авторизованного пользователя */}
      <div className="user-name" style={{ marginTop: 8, marginBottom: 16 }}>
        Вы вошли как: {userName}
      </div>

      {/* Центрированный текстовый блок */}
      <div className="center-block" style={{ textAlign: 'center', margin: '12px 0 20px' }}>
        <p>Добро пожаловать в панель управления вашими машинами. Выберите раздел ниже для просмотра данных.</p>
      </div>

      {/* Три кнопки-табов по центру */}
      <div className="tabs" style={{ display: 'flex', justifyContent: 'center', gap: 12, marginBottom: 12 }}>
        {[
          { key: 'info', label: 'Общая информация' },
          { key: 'TO', label: 'ТО' },
          { key: 'claims', label: 'Рекламации' },
        ].map((t) => (
          <button
            key={t.key}
            className={`btn ${activeTab === t.key ? 'active' : ''}`}
            onClick={() => setActiveTab(t.key)}
            style={{ padding: '10px 16px' }}
          >
            {t.label}
          </button>
        ))}
      </div>

      {/* Таблица: только для "Общая информация" */}
      <div className="table-section" style={{ padding: '0 8px' }}>
        {activeTab === 'info' && (
          <TableWithFilters
            data={sorted}
            onRowClick={(row) => navigate(`/machines/${row.id}`)}
            filters={filters}
            setFilters={setFilters}
          />
        )}
        {activeTab === 'TO' && <div>Заглушка для раздела ТО</div>}
        {activeTab === 'claims' && <div>Заглушка для раздела Рекламации</div>}
      </div>
    </div>
  );
}

// Компонент таблицы с фильтрами
function TableWithFilters({ data, onRowClick, filters, setFilters }) {
  // Локальные значения фильтров берём из пропсов, чтобы родитель мог держать состояние
  const handleChange = (field) => (e) =>
    setFilters({ ...filters, [field]: e.target.value });

  const formatDate = (d) => {
    const date = new Date(d);
    if (Number.isNaN(date)) return d;
    return date.toISOString().slice(0, 10);
  };

  const rows = data;

  return (
    <div className="table-container" style={{ overflowX: 'auto' }}>
      <div
        className="filters"
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(7, 1fr)',
          gap: 8,
          marginBottom: 8,
        }}
      >
        <input placeholder="Дата" value={filters.date} onChange={handleChange('date')} />
        <input placeholder="Машина" value={filters.model_machine} onChange={handleChange('model_machine')} />
        <input placeholder="Двигатель" value={filters.model_engine} onChange={handleChange('model_engine')} />
        <input placeholder="Трансмиссия" value={filters.model_transmission} onChange={handleChange('model_transmission')} />
        <input placeholder="Управляемый мост" value={filters.model_controlled_bridge} onChange={handleChange('model_controlled_bridge')} />
        <input placeholder="Ведущий мост" value={filters.model_driving_bridge} onChange={handleChange('model_driving_bridge')} />
        <input placeholder="Серийный номер" value={filters.serial_number_machine} onChange={handleChange('serial_number_machine')} />
      </div>

      <table className="data-table" style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr>
            <th>Дата отгрузки с завода</th>
            <th>Машина</th>
            <th>Двигатель</th>
            <th>Трансмиссия</th>
            <th>Управляемый мост</th>
            <th>Ведущий мост</th>
            <th>Серийный номер машины</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => (
            <tr key={r.id} onClick={() => onRowClick?.(r)} style={{ cursor: 'pointer' }}>
              <td>{formatDate(r.date_shipment_from_factory)}</td>
              <td>{r.model_machine}</td>
              <td>{r.model_engine}</td>
              <td>{r.model_transmission}</td>
              <td>{r.model_controlled_bridge}</td>
              <td>{r.model_driving_bridge}</td>
              <td>{r.serial_number_machine}</td>
            </tr>
          ))}
          {rows.length === 0 && (
            <tr>
              <td colSpan={7} style={{ textAlign: 'center' }}>
                Нет данных
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}
